// План: specs/disputes.md, блок 5 (5.1). Кейсы: .qa/tests/disputes/DSP-010.md (#e928c2), DSP-011.md (#c6538a).
// Несколько ролей: клиент открывает спор «בורר אנושי», נותן שירות соглашается, арбитр (0500000006) решает из панели /arbitration,
// обе стороны подтверждают решение — деньги делятся.
// Меняет деньги тестовых аккаунтов → @data. Сделка QA-AUTO-… → id в qa-auto-created.jsonl (helpers.getEscrowDeal).
// Записан 02.11 без прогона: селекторы шагов сторон (согласие на бורר, экран решения) подтвердить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { getEscrowDeal, openArbiterDispute, openTab, waitWithReload } from './helpers';

test.describe.configure({ mode: 'serial', retries: 0 });

const RELEASE = 60; // ₪ нותן/ת השירות из сделки ₪100 (helpers.getEscrowDeal создаёт сделку на ₪100)
const REFUND = 40; // ₪ обратно משלם/ת

/** «היתרה שלך» на /wallet в ₪ (USD-строка «≈ $…» рядом не мешает — берём сумму с ₪). */
async function readBalance(page: Page): Promise<number> {
  await page.goto('/wallet');
  await expect(page.getByText('היתרה שלך').first()).toBeVisible();
  const body = await page.locator('body').innerText();
  const after = body.slice(body.indexOf('היתרה שלך'));
  const m = after.match(/₪\s?([\d,]+(?:\.\d{1,2})?)/);
  if (!m) throw new Error('Не нашёл сумму в ₪ рядом с «היתרה שלך»');
  return Number(m[1].replace(/,/g, ''));
}

/** Сторона открывает решение арбитра на вкладке «מחלוקת». */
async function openArbiterProposal(page: Page, dealId: string) {
  await page.goto(`/deals/${dealId}?tab=dispute`);
  const view = page.getByRole('button', { name: /צפייה בהצעת/ });
  const title = page.getByText('הצעת פתרון בעזרת בורר אנושי').first();
  await waitWithReload(page, view.or(title));
  if (await view.first().isVisible().catch(() => false)) await view.first().click();
  await expect(title).toBeVisible();
}

test.describe('מחלוקות — בורר אנושי: החלטה מהפאנל', () => {
  test('בורר שולח החלטה ₪60/₪40 → שני הצדדים מאשרים → הכסף מתחלק @iphone @data #e928c2 #c6538a', async ({ asUser }) => {
    test.skip(
      process.env.QA_ALLOW_ARBITER_FEE !== '1',
      'Согласие на «בורר אנושי» может списать сбор ₪150 с тестового баланса — задай QA_ALLOW_ARBITER_FEE=1 (решение пользователя).',
    );
    const client = await asUser('client');
    const provider = await asUser('provider');
    const arbitrator = await asUser('arbitrator');

    const { id, title } = await getEscrowDeal(client, provider, 'ARBITER');

    // 1. Клиент открывает спор с בורר אנושי.
    await openArbiterDispute(client, id);

    // 2. נותן שירות соглашается на בורר אנושי (не «דחייה» — это DSP-007).
    await provider.goto(`/deals/${id}?tab=dispute`);
    await waitWithReload(provider, provider.getByText('האם את/ה מאשר גישור בעזרת בורר אנושי?'));
    await provider.getByRole('button', { name: /^אישור/ }).first().click();
    // Если открылось подтверждение сбора арбитра — подтвердить (разрешено QA_ALLOW_ARBITER_FEE=1).
    const feeConfirm = provider.getByRole('button', { name: /תשלום|אישור ותשלום|המשך/ }).last();
    if (await feeConfirm.isVisible().catch(() => false)) await feeConfirm.click();

    // 3. Арбитр: спор появился в панели как «ממתין להחלטתך», решение ₪60 / ₪40.
    await arbitrator.goto('/arbitration');
    await expect(arbitrator.getByText('מחלוקות לבוררות').first()).toBeVisible();
    const row = arbitrator.getByRole('button').filter({ hasText: title || id.slice(0, 8) }).filter({ hasText: 'ממתין להחלטתך' });
    await waitWithReload(arbitrator, row);
    await row.first().click();
    await arbitrator.waitForURL(/\/arbitration\/[0-9a-f-]{20,}/);
    await expect(arbitrator.getByText('ממתין להחלטתך').first()).toBeVisible();
    await arbitrator.getByRole('textbox', { name: /כמה לשחרר לנותן\/ת השירות/ }).fill(String(RELEASE));
    await arbitrator.getByRole('textbox', { name: 'נימוק' }).fill('QA-AUTO: החלטת בורר אוטומטית — פיצול 60/40.');
    await expect(arbitrator.getByText(`לשחרר ₪${RELEASE} לנותן/ת השירות ולהחזיר ₪${REFUND} למשלם/ת.`)).toBeVisible();
    const send = arbitrator.getByRole('button', { name: 'שליחת ההחלטה לשני הצדדים' });
    await expect(send).not.toHaveAttribute('aria-disabled', 'true');
    await send.click();

    // 4. Балансы до подтверждения (сбор, если был, уже списан).
    const providerBefore = await readBalance(provider);
    const clientBefore = await readBalance(client);

    // 5. Обе стороны видят решение арбитра (S-45, #c6538a) и подтверждают.
    for (const page of [client, provider]) {
      await openArbiterProposal(page, id);
      await expect(page.getByText('בורר SafePay').first()).toBeVisible();
      await expect(page.getByText(`₪${RELEASE}`).first()).toBeVisible();
      await expect(page.getByText(`₪${REFUND}`).first()).toBeVisible();
      await expect(page.getByText('מעבר לבורר אנושי')).toHaveCount(0);
    }

    await client.getByRole('button', { name: 'אישור ההצעה' }).click();
    await expect(client.getByText(/אישרת את ההצעה/).first()).toBeVisible();
    await expect(client.getByText(/ממתין לצד השני/).first()).toBeVisible();

    await provider.getByRole('button', { name: 'אישור ההצעה' }).click();

    // 6. Панель арбитра обновилась; деньги поделились; в журнале «המחלוקת הוכרעה».
    await arbitrator.goto('/arbitration');
    const doneRow = arbitrator
      .getByRole('button')
      .filter({ hasText: title || id.slice(0, 8) })
      .filter({ hasText: 'ההצעה אושרה על ידי שני הצדדים' });
    await waitWithReload(arbitrator, doneRow);

    await expect.poll(() => readBalance(provider), { timeout: 60_000 }).toBeCloseTo(providerBefore + RELEASE, 2);
    await expect.poll(() => readBalance(client), { timeout: 60_000 }).toBeCloseTo(clientBefore + REFUND, 2);

    for (const page of [client, provider]) {
      await page.goto(`/deals/${id}`);
      await openTab(page, 'היסטוריה');
      await waitWithReload(page, page.getByText('המחלוקת הוכרעה').first());
    }
  });
});
